"""Import identity and published clocks must describe the same generated bytes."""

import hashlib
import json
import os
from pathlib import Path

import av
import numpy as np
import pytest
from badminton import ingest
from badminton.schemas import Annotations
from badminton.storage import Store
from badminton.video import SourceChangedError, resolve_source


@pytest.fixture
def import_sources(tmp_path):
    def encode(name, count, rate, size):
        path = tmp_path / name
        with av.open(str(path), "w") as container:
            stream = container.add_stream("libx264", rate=rate)
            stream.width = stream.height = size
            stream.pix_fmt = "yuv420p"
            for index in range(count):
                frame = av.VideoFrame.from_ndarray(
                    np.full((size, size, 3), index * 25, np.uint8), format="rgb24"
                )
                for packet in stream.encode(frame):
                    container.mux(packet)
            for packet in stream.encode():
                container.mux(packet)
        return path.read_bytes()

    original = encode("generated-original.mp4", 3, 25, 32)
    replacement = encode("generated-replacement.mp4", 6, 20, 48)
    # Ordinary MP4 free boxes give both valid sources the same byte length.
    target_size = max(len(original), len(replacement)) + 64

    def padded(content):
        size = target_size - len(content)
        return content + size.to_bytes(4, "big") + b"free" + bytes(size - 8)

    original, replacement = padded(original), padded(replacement)
    source = tmp_path / "source.mp4"
    source.write_bytes(original)
    return tmp_path, Store(tmp_path / "processed"), source, original, replacement


def artifact_bytes(folder):
    return {
        path.relative_to(folder).as_posix(): path.read_bytes()
        for path in folder.rglob("*")
        if path.is_file()
    }


def changed_decoder(monkeypatch, source, replacement, when, restore_mtime=False):
    original_open = ingest.open_media
    previous_stat = source.stat()
    changes = []

    def change():
        if not changes:
            source.write_bytes(replacement)
            if restore_mtime:
                os.utime(
                    source,
                    ns=(previous_stat.st_atime_ns, previous_stat.st_mtime_ns),
                )
            changes.append(True)

    def open_changed(*args, **kwargs):
        change()
        return original_open(*args, **kwargs)

    if when == "before-open":
        monkeypatch.setattr(ingest, "open_media", open_changed)
        progress = None
    else:

        def progress(_fraction):
            change()

    return progress, changes


@pytest.mark.parametrize("when", ["before-open", "during-progress"])
@pytest.mark.parametrize("restore_mtime", [False, True])
def test_changed_source_cannot_publish_a_new_import(
    import_sources, monkeypatch, when, restore_mtime
):
    root, store, source, original, replacement = import_sources
    progress, changes = changed_decoder(
        monkeypatch, source, replacement, when, restore_mtime
    )
    with pytest.raises(SourceChangedError, match="changed"):
        ingest.inspect_video(source, "singles", store, root, progress)
    assert changes == [True]
    assert source.read_bytes() == replacement
    assert store.videos() == []
    old_id = hashlib.sha256(original).hexdigest()[:16]
    assert artifact_bytes(store.data / old_id) == {}


@pytest.mark.parametrize("when", ["before-open", "during-progress"])
def test_failed_changed_reimport_preserves_all_published_artifacts_and_truth(
    import_sources, monkeypatch, when
):
    root, store, source, original, replacement = import_sources
    video = ingest.inspect_video(source, "singles", store, root)
    video.update(
        source_type="upload",
        source={"original_name": "Reviewed match.mp4"},
        name="Reviewed match.mp4",
        review_start_frame=1,
    )
    store.register(video)
    document = store.annotations(video["id"]).model_dump()
    document["events"] = [
        {
            "id": "reviewed-shot",
            "rally_id": "R1",
            "kind": "shot",
            "frame": 1,
            "family": "clear",
            "side": "forehand",
        }
    ]
    store.save_annotations(video["id"], Annotations.model_validate(document))
    saved = store.annotations(video["id"]).model_dump()
    folder = store.data / video["id"]
    runs = folder / "runs"
    runs.mkdir()
    (runs / "generated-original.json").write_text(
        '{"generated":true,"originalPrediction":true}\n', encoding="utf-8"
    )
    published = artifact_bytes(folder)
    progress, _changes = changed_decoder(monkeypatch, source, replacement, when)
    with pytest.raises(SourceChangedError, match="changed"):
        ingest.inspect_video(source, "singles", store, root, progress)
    assert store.video(video["id"]) == video
    assert store.annotations(video["id"]).model_dump() == saved
    assert artifact_bytes(folder) == published
    assert source.read_bytes() == replacement
    with pytest.raises(SourceChangedError, match="changed"):
        resolve_source(video, root)
    # A user-controlled source is never restored by the importer. The test alone
    # restores its generated input to verify the old registration remains usable.
    source.write_bytes(original)
    assert resolve_source(video, root) == source


@pytest.mark.parametrize("restore_mtime", [False, True])
def test_change_during_digest_read_does_not_publish_mixed_identity(
    import_sources, monkeypatch, restore_mtime
):
    root, store, source, original, replacement = import_sources
    original_open = Path.open
    previous_stat = source.stat()
    changes = []

    class ChangingReader:
        def __init__(self, handle):
            self.handle = handle

        def __enter__(self):
            self.handle.__enter__()
            return self

        def __exit__(self, *args):
            return self.handle.__exit__(*args)

        def __getattr__(self, name):
            return getattr(self.handle, name)

        def read(self, *args):
            content = self.handle.read(*args)
            if content and not changes:
                changes.append(True)
                source.write_bytes(replacement)
                if restore_mtime:
                    os.utime(
                        source,
                        ns=(previous_stat.st_atime_ns, previous_stat.st_mtime_ns),
                    )
            return content

    def opening(path, mode="r", *args, **kwargs):
        handle = original_open(path, mode, *args, **kwargs)
        if path == source and mode == "rb" and not changes:
            return ChangingReader(handle)
        return handle

    monkeypatch.setattr(Path, "open", opening)
    with pytest.raises(SourceChangedError, match="changed"):
        ingest.inspect_video(source, "singles", store, root)
    assert changes == [True]
    assert store.videos() == []
    assert artifact_bytes(store.data / hashlib.sha256(original).hexdigest()[:16]) == {}


def test_stable_source_and_same_content_duplicate_keep_native_clock(import_sources):
    root, store, source, original, _replacement = import_sources
    video = ingest.inspect_video(source, "singles", store, root)
    folder = store.data / video["id"]
    published = artifact_bytes(folder)
    duplicate = ingest.inspect_video(source, "singles", store, root)
    assert duplicate == video == store.video(video["id"])
    assert video["sha256"] == hashlib.sha256(original).hexdigest()
    assert (video["frame_count"], video["width"], video["height"]) == (3, 32, 32)
    assert video["duration_s"] == pytest.approx(0.12)
    assert json.loads((folder / "timestamps.json").read_text()) == pytest.approx(
        [0, 0.04, 0.08]
    )
    assert artifact_bytes(folder) == published
    with pytest.raises(ValueError, match="different match format"):
        ingest.inspect_video(source, "doubles", store, root)
    assert artifact_bytes(folder) == published


def test_metadata_only_change_does_not_reject_unchanged_source_bytes(import_sources):
    root, store, source, original, _replacement = import_sources

    def progress(_fraction):
        observed = source.stat()
        os.utime(source, ns=(observed.st_atime_ns, observed.st_mtime_ns + 1000000))

    video = ingest.inspect_video(source, "singles", store, root, progress)
    assert video["sha256"] == hashlib.sha256(original).hexdigest()
    assert source.read_bytes() == original
    assert resolve_source(video, root) == source


def test_original_digest_io_failure_remains_the_initiating_error(
    import_sources, monkeypatch
):
    root, store, source, _original, _replacement = import_sources
    original_open = Path.open
    failure = PermissionError("original source read failure")

    def opening(path, mode="r", *args, **kwargs):
        if path == source and mode == "rb":
            raise failure
        return original_open(path, mode, *args, **kwargs)

    monkeypatch.setattr(Path, "open", opening)
    with pytest.raises(PermissionError) as caught:
        ingest.inspect_video(source, "singles", store, root)
    assert caught.value is failure
    assert store.videos() == []


def test_final_source_read_failure_leaves_prior_import_intact(
    import_sources, monkeypatch
):
    root, store, source, _original, _replacement = import_sources
    video = ingest.inspect_video(source, "singles", store, root)
    published = artifact_bytes(store.data / video["id"])
    original_open = Path.open
    failure = PermissionError("source became unreadable during decoding")

    def progress(_fraction):
        def opening(path, mode="r", *args, **kwargs):
            if path == source and mode == "rb":
                raise failure
            return original_open(path, mode, *args, **kwargs)

        monkeypatch.setattr(Path, "open", opening)

    with pytest.raises(PermissionError) as caught:
        ingest.inspect_video(source, "singles", store, root, progress)
    assert caught.value is failure
    assert store.video(video["id"]) == video
    assert artifact_bytes(store.data / video["id"]) == published


def test_initiating_decoder_failure_is_not_masked_by_changed_source(
    import_sources, monkeypatch
):
    root, store, source, _original, replacement = import_sources
    failure = ValueError("initiating decoder failure")

    def opening(*args, **kwargs):
        source.write_bytes(replacement)
        raise failure

    monkeypatch.setattr(ingest, "open_media", opening)
    with pytest.raises(ValueError) as caught:
        ingest.inspect_video(source, "singles", store, root)
    assert caught.value is failure
    assert store.videos() == []
